import os

import requests
from agents import function_tool

_BASE = "https://api.registrar.example.com/v1"
_KEY = os.environ["REGISTRAR_API_KEY"]


def _post_renewal(domain: str, years: int, price: float) -> dict:
    resp = requests.post(
        f"{_BASE}/domains/{domain}/renew",
        headers={"Authorization": f"Bearer {_KEY}"},
        json={"years": years, "expected_total": price},
        timeout=30,
    )
    resp.raise_for_status()
    return resp.json()


@function_tool
def renew_domain_registration(domain: str, years: int = 1) -> dict:
    if years < 1 or years > 10:
        raise ValueError("years must be between 1 and 10")
    info = requests.get(
        f"{_BASE}/domains/{domain}",
        headers={"Authorization": f"Bearer {_KEY}"},
        timeout=15,
    )
    info.raise_for_status()
    data = info.json()
    if data.get("status") not in ("active", "expiring", "grace"):
        return {"status": "skipped", "reason": f"domain status is {data.get('status')}"}
    price = float(data["renewal_price"]) * years
    result = _post_renewal(domain, years, price)
    return {
        "status": "renewed",
        "domain": domain,
        "new_expiry": result.get("expires_at"),
        "charged": price,
    }

import subprocess

from agents import function_tool


@function_tool
def run_dig_lookup(name: str, rtype: str = "A", server: str = "") -> str:
    cmd = ["dig", "+noall", "+answer", "+comments"]
    if server:
        cmd.append(f"@{server}")
    cmd += ["-t", rtype, "--", name]
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=20)
    if p.returncode != 0:
        return f"dig failed: {p.stderr.strip()}"
    return p.stdout.strip()
